// Generalitat: calendarios oficiales 2026 y 2027. No incluye fiestas locales ni la excepción de Aran.
const labels={'01-01':'Año Nuevo','01-06':'Reyes','05-01':'Fiesta del Trabajo','06-24':'Sant Joan','08-15':'La Asunción','09-11':'Diada Nacional de Cataluña','10-12':'Fiesta Nacional de España','11-01':'Todos los Santos','12-06':'Día de la Constitución','12-08':'La Inmaculada','12-25':'Navidad','12-26':'Sant Esteve'};
const official={2026:['01-01','01-06','04-03','04-06','05-01','06-24','08-15','09-11','10-12','12-08','12-25','12-26'],2027:['01-01','01-06','03-26','03-29','05-01','06-24','09-11','10-12','11-01','12-06','12-08','12-25']};
function easter(year){const a=year%19,b=Math.floor(year/100),c=year%100,d=Math.floor(b/4),e=b%4,f=Math.floor((b+8)/25),g=Math.floor((b-f+1)/3),h=(19*a+b-d-g+15)%30,i=Math.floor(c/4),k=c%4,l=(32+2*e+2*i-h-k)%7,m=Math.floor((a+11*h+22*l)/451),month=Math.floor((h+l-7*m+114)/31),day=(h+l-7*m+114)%31+1;return new Date(Date.UTC(year,month-1,day,12));}
export function holidayEvents(year){const date=easter(year),friday=new Date(+date-2*86400000).toISOString().slice(5,10),monday=new Date(+date+86400000).toISOString().slice(5,10),names={...labels,[friday]:'Viernes Santo',[monday]:'Lunes de Pascua'},dates=official[year]||Object.keys(names).filter(d=>new Date(year+'-'+d+'T12:00:00Z').getUTCDay()!==0);return dates.map(d=>({id:'holiday:'+year+':'+d,date:year+'-'+d,title:names[d]||'Festivo',description:official[year]?'Festivo oficial de Cataluña. No incluye fiestas municipales ni las sustituciones de Aran.':'Previsión anual orientativa: pendiente de confirmar con el calendario oficial de este año.',location:'Cataluña',time:'Todo el día',url:official[year]?'https://treball.gencat.cat/ca/ambits/relacions_laborals/ci/calendari_laboral/calendari-festes-'+year+'/':'https://treball.gencat.cat/ca/ambits/relacions_laborals/ci/calendari_laboral/',holiday:true,provisional:!official[year]}));}
export function materializeHolidays(events,year){return [...events.filter(e=>!e.holiday),...holidayEvents(year)];}
